	ambiguous := runFiz(t, fixture, "models", "gpt")
	if ambiguous.exitCode != 1 {
		t.Fatalf("ambiguous shortform exit=%d, want 1 stdout=%s stderr=%s", ambiguous.exitCode, ambiguous.stdout, ambiguous.stderr)
