	for _, want := range []string{"ambiguous model ref", "alpha/gpt-5.5", "beta/gpt-5.5"} {
		if !strings.Contains(ambiguous.stderr, want) {
			t.Fatalf("ambiguous output missing %q:\n%s", want, ambiguous.stderr)
